using System.IO;

namespace MediPassPlus.Application.Records;

/// <summary>
/// Private storage for report files. The name is generated by the implementation, the location is never inside the
/// repository or <c>wwwroot</c>, and the only way to write or read a file is an endpoint that has already checked
/// ownership or an active grant (FR-REC-06, FR-PRV-05, NFR-SEC-09, ADR-0015 decision 6). Nothing in this contract
/// accepts a client file name or a public path.
/// </summary>
public interface IReportStorage
{
    /// <summary>
    /// Writes <paramref name="content"/> under a new random name and returns that name and the byte count.
    /// </summary>
    /// <param name="content">The file bytes, positioned at the start.</param>
    /// <param name="contentType">A media type accepted by <see cref="ReportFileValidator"/>; it selects the extension.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <returns>The stored name and the number of bytes written.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="content"/> is null.</exception>
    /// <exception cref="ArgumentOutOfRangeException">
    /// <paramref name="contentType"/> is not one of the three supported formats.
    /// </exception>
    /// <exception cref="ReportFileSizeException">
    /// The stream is empty or longer than <see cref="ReportFileValidator.MaxSizeBytes"/>; the exception carries the
    /// exact reason. The partial file is removed before the exception leaves, so a refusal never leaves bytes behind.
    /// </exception>
    Task<StoredReportFile> SaveAsync(
        Stream content,
        string contentType,
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Removes a stored file. It is used to undo a write when the database commit that should have recorded the row
    /// fails, so the file and the record never disagree.
    /// </summary>
    /// <param name="storedFileName">The name returned by <see cref="SaveAsync"/>, never a client-supplied name.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <returns>True when a file was removed, false when it was already gone.</returns>
    /// <exception cref="ArgumentException">
    /// The name is empty, or it is not a plain file name: a value that could escape the storage root is refused rather
    /// than resolved.
    /// </exception>
    Task<bool> DeleteAsync(string storedFileName, CancellationToken cancellationToken = default);

    /// <summary>
    /// Opens a stored file for reading. The caller must have authorized the access before calling this method, because
    /// the storage layer only enforces path safety and never ownership or grants (FR-PRV-05, ADR-0015 decision 6).
    /// </summary>
    /// <param name="storedFileName">The name returned by <see cref="SaveAsync"/>, never a client-supplied name.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <returns>
    /// A readable stream positioned at the start, or <see langword="null"/> when no file with that name exists.
    /// The caller owns the returned stream.
    /// </returns>
    /// <exception cref="ArgumentException">
    /// The name is empty, or it is not a plain file name: a value that could escape the storage root is refused rather
    /// than resolved.
    /// </exception>
    Task<Stream?> OpenReadAsync(string storedFileName, CancellationToken cancellationToken = default);
}
